import React from "react";
import { render, screen } from "@testing-library/react";
import { ThemeProvider, ColorModeProvider, useColorMode, useTheme } from ".";
import { ThemeTokens } from "@airbus/styles";

// using typeassertion to override theme type to shorter version,
// since we are testing if the mode is picked up correctly
const Consumer = () => {
  const theme = useTheme() as ThemeTokens;
  const mode = useColorMode();
  return <p>My text color is: {theme.color.text.neutral.default[mode]}</p>;
};

describe("useColorMode", () => {
  it("should provide the default colors when no ColorModeProvider is used", () => {
    render(
      <ThemeProvider>
        <Consumer />
      </ThemeProvider>
    );
    expect(screen.getByText(/^My text color is:/)).toHaveTextContent(
      "My text color is: #14171d"
    );
  });

  it("should provide the right colors to ColorModeProvider children", () => {
    render(
      <ThemeProvider>
        <ColorModeProvider mode="dark">
          <Consumer />
        </ColorModeProvider>
      </ThemeProvider>
    );
    expect(screen.getByText(/^My text color is:/)).toHaveTextContent(
      "My text color is: #ffffff"
    );
  });
});
